//! Required HR noShade boolean reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><hr id=list data-kind=MiXeD noshade=legacy><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://hr-no-shade.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn hr_no_shade_canonical_boolean_accessor_and_actual_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),P=HTMLHRElement.prototype,a=Object.getOwnPropertyDescriptor(P,'noShade');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get noShade'||a.set.name!=='set noShade'||Object.hasOwn(x,'noShade')||x.noShade!==true||x.getAttribute('noshade')!=='legacy'||x.getAttribute('data-kind')!=='MiXeD'||document.createElement('hr').noShade!==false)throw 'canonical noshade boolean';"#);}
#[test]
fn hr_no_shade_native_boolean_conversion_identity_and_observer_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),old=x.getAttributeNode('noshade'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.noShade=false;var records=watch.takeRecords();if(x.noShade!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='noshade')throw 'false removes actual attribute';var calls=0;x.noShade={toString:function(){calls++;return '';},valueOf:function(){calls++;return 0;}};var attr=x.getAttributeNode('noshade');records=watch.takeRecords();if(calls||x.noShade!==true||attr===null||attr.value!==''||records.length!==1||records[0].oldValue!==null||x.getAttribute('data-kind')!=='MiXeD'||document.getElementById('neighbor').value!=='seed')throw 'boolean conversion keeps actual record';x.noShade='';if(x.noShade!==false||attr.ownerElement!==null)throw 'empty string is false';"#);}
#[test]
fn hr_no_shade_inert_exact_namespace_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:hr');if(!(x instanceof HTMLHRElement)||x.noShade!==false)throw 'inert absent noshade';x.setAttributeNS('urn:foreign','noshade','foreign');x.setAttributeNS(null,'NOSHADE','upper');if(x.noShade!==false)throw 'exact noshade namespace and case';x.noShade=true;var attr=x.getAttributeNodeNS(null,'noshade');if(x.noShade!==true||attr===null||attr.value!=='')throw 'inert actual boolean';x.removeAttributeNS('urn:foreign','noshade');x.removeAttributeNS(null,'NOSHADE');var clone=x.cloneNode(false),copy=document.importNode(x,false);if(!(clone instanceof HTMLHRElement)||!(copy instanceof HTMLHRElement)||clone.noShade!==true||copy.noShade!==true||copy.ownerDocument!==document||clone.getAttributeNode('noshade')===attr)throw 'independent boolean copies';clone.noShade=false;if(x.noShade!==true||copy.noShade!==true||clone.noShade!==false)throw 'independent noshade removal';"#);}

#[test]
fn hr_no_shade_truthiness_does_not_invoke_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),a=Object.getOwnPropertyDescriptor(HTMLHRElement.prototype,'noShade'),calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.noShade!==false||x.hasAttribute('noshade'))throw 'false boolean value';}for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('boolean'),BigInt(1),author]){a.set.call(x,value);if(x.noShade!==true||x.getAttribute('noshade')!==''||calls)throw 'true boolean value';}a.set.call(x);if(x.noShade!==false||calls||x.getAttribute('data-kind')!=='MiXeD')throw 'missing boolean argument';"#);}
#[test]
fn hr_no_shade_brand_precedes_hooks_and_keeps_author_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),C=HTMLHRElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'noShade'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('p'),document.createElement('ul'),document.createElement('li'),document.createElement('dl'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','hr'),new Document().createElementNS('http://www.w3.org/1999/xhtml','HR')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'noshade getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return '';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'noshade setter brand';}Object.defineProperty(x,'noShade',{value:'author',writable:true,configurable:true});a.set.call(x,false);if(x.noShade!=='author'||x.hasAttribute('noshade'))throw 'canonical attribute authority';delete x.noShade;if(x.noShade!==false||Object.hasOwn(x,'noShade'))throw 'restored inherited boolean';delete window.HTMLHRElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved canonical interface';"#);}
#[test]
fn hr_no_shade_raw_attribute_aliases_observe_presence_and_preserve_exact_backing(){let(mut d,mut f,mut p)=fixture();for inert in [false,true]{run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','hr');x.noShade=true;"}else{"var x=document.getElementById('list');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('noshade'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var key of ['value','nodeValue','textContent']){a[key]='R\ud800'+key;if(x.noShade!==true||a.value!=='R\ud800'+key||x.getAttributeNode('noshade')!==a)throw 'raw boolean backing';}var old=a.value;x.noShade=true;var records=watch.takeRecords();if(x.noShade!==true||a.value!==''||records.length!==4||records[3].oldValue!==old||x.getAttributeNode('noshade')!==a)throw 'boolean normalization uses current Attr';x.removeAttribute('noshade');if(x.noShade!==false||a.ownerElement!==null)throw 'actual boolean removal';x.setAttributeNS('urn:foreign','noshade','foreign');x.setAttributeNS(null,'NOSHADE','upper');if(x.noShade!==false)throw 'exact noshade authority';x.setAttributeNS(null,'noshade','A\udfffZ');var clone=x.cloneNode(false);if(!x.noShade||!clone.noShade||clone.getAttributeNodeNS(null,'noshade').value!=='A\udfffZ'||clone.getAttributeNodeNS(null,'noshade')===x.getAttributeNodeNS(null,'noshade'))throw 'raw presence copy';"#);}}
#[test]
fn hr_no_shade_saved_child_origin_refuses_before_observation_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLHRElement.prototype,'noShade');a.set.call(x,false);if(a.get.call(x)!==false)throw 'same origin boolean';");p.set_location(&crate::navigation::address("https://other-noshade.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,true);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://hr-no-shade.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(x.noShade!==false)throw 'origin refusal preserves value';a.set.call(x,true);if(!a.get.call(x)||x.getAttribute('noshade')!=='')throw 'saved boolean recovery';");}

#[test]
fn hr_no_shade_native_adoption_copy_and_template_keep_real_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('list'),attr=x.getAttributeNode('noshade'),first=x.firstChild,copy=x.cloneNode(true),doc=new Document();if(!copy.noShade||copy.getAttribute('noshade')!=='legacy'||copy.firstChild!==null||first!==null)throw 'native boolean clone';doc.adoptNode(x);if(!x.noShade||x.getAttributeNode('noshade')!==attr||attr.ownerDocument!==doc||x.firstChild!==first)throw 'actual boolean adoption';document.adoptNode(x);document.body.appendChild(x);copy.noShade=false;if(!x.noShade||copy.noShade||attr.ownerElement!==x||x.getAttribute('data-kind')!=='MiXeD')throw 'independent copy removal';var template=document.createElement('template'),leaf=x.cloneNode(false);template.content.appendChild(leaf);document.body.appendChild(template);if(!leaf.noShade||leaf.ownerDocument!==template.content.ownerDocument||leaf.getAttribute('noshade')!=='legacy')throw 'actual boolean template parking';"#);}
#[test]
fn hr_no_shade_writer_resource_refusal_is_atomic_and_recovers(){for inert in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','hr');"}else{"var x=document.getElementById('list');x.noShade=false;"});run(&mut d,&mut f,&mut p,"var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute("x.noShade=true;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.noShade!==false||watch.takeRecords().length)throw 'atomic noshade refusal';x.noShade=true;var records=watch.takeRecords();if(x.noShade!==true||x.getAttribute('noshade')!==''||records.length!==1||records[0].oldValue!==null)throw 'fresh boolean recovery';");}}}
#[test]
fn hr_no_shade_reads_charge_names_work_and_deadline_without_string_copy_or_retained_growth(){for inert in [false,true]{for mode in 0..3{let(mut d,mut f,mut p)=fixture();let object=if inert{let Value::Host(object)=p.runtime.execute("var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','hr');x.noShade=true;x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert OL")};object}else{node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("list")).unwrap())};let before=format!("{:?}",d.nodes);let retained=p.state.retained;let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),_=>{p.state.retained_limit=retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.hr_no_shade_get(object);if mode==2{assert!(matches!(result,Ok(Value::Bool(true))));}else{assert!(result.is_err());}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.hr_no_shade_get(object),Ok(Value::Bool(true))));}}}
#[test]
fn hr_no_shade_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["hr"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById('list');");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.noShade='exact';");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.noShade='exact';");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('noshade');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('noshade')!==oldValue||watch.takeRecords().length)throw 'atomic gauge lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('noshade')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.noShade!==source.noShade||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}

#[test]
fn hr_no_shade_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["hr"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.noShade='exact';var first=source.firstChild,attr=source.getAttributeNode('noshade');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('noshade')!==attr||source.noShade!==true||source.parentNode!==target)throw 'reserved native gauge connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}

#[test]
fn hr_no_shade_clone_import_active_content_guards_preserve_source(){
 let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag,attrs,..}=&mut node.kind{if tag=="hr"{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','hr'),frame=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');source.appendChild(frame);");for code in ["x.cloneNode(true);","document.importNode(source,true);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==frame||frame.parentNode!==source||source.ownerDocument!==doc||x.noShade!==true)throw 'active content copy guard';");}
}


#[test]
fn hr_no_shade_independent_align_and_color_keep_actual_handles(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var x of [document.getElementById('list'),new Document().createElementNS('http://www.w3.org/1999/xhtml','t:hr')]){x.align='marker';x.color='arbitrary';var align=x.getAttributeNode('align'),color=x.getAttributeNode('color'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.noShade=true;var attr=x.getAttributeNode('noshade');x.noShade=false;x.noShade='false';var records=watch.takeRecords();if(x.noShade!==true||x.getAttribute('noshade')!==''||x.align!=='marker'||x.color!=='arbitrary'||x.getAttributeNode('align')!==align||x.getAttributeNode('color')!==color||align.value!=='marker'||color.value!=='arbitrary'||attr.ownerElement!==null||attr.value!==''||x.getAttributeNode('noshade')===attr||records.length!==3||records[0].attributeName!=='noshade'||records[1].attributeName!=='noshade'||records[2].attributeName!=='noshade'||records[1].oldValue!==''||records[2].oldValue!==null)throw 'independent separator reflectors';}");}
#[test]
fn hr_no_shade_camel_case_property_and_exact_lower_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('list'),P=HTMLHRElement.prototype;if(Object.getOwnPropertyDescriptor(P,'noshade')!==undefined)throw 'no lowercase prototype alias';x.noshade='author';x.noShade=false;if(x.noshade!=='author'||x.noShade!==false||x.hasAttribute('noshade'))throw 'camel property separate from author key';x.noShade=true;if(x.noshade!=='author'||x.noShade!==true||x.getAttribute('noshade')!=='')throw 'camel property reflects lowercase attribute';var y=new Document().createElementNS('http://www.w3.org/1999/xhtml','t:hr');y.setAttributeNS(null,'noShade','wrong case');if(y.noShade!==false)throw 'exact inert attribute case';y.noShade=true;if(y.getAttributeNS(null,'noShade')!=='wrong case'||y.getAttributeNS(null,'noshade')!==''||y.noShade!==true)throw 'independent exact spelling';");}

#[test]
fn hr_no_shade_filtered_observers_use_lowercase_attribute_and_exact_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var x of [document.getElementById('list'),new Document().createElementNS('http://www.w3.org/1999/xhtml','t:hr')]){x.setAttribute('noshade','R\ud800Z');var attr=x.getAttributeNode('noshade'),watch=new MutationObserver(function(){}),wrong=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeFilter:['noshade'],attributeOldValue:true});wrong.observe(x,{attributes:true,attributeFilter:['noShade'],attributeOldValue:true});x.noShade=true;x.noShade=false;var records=watch.takeRecords();if(records.length!==2||records[0].attributeName!=='noshade'||records[1].attributeName!=='noshade'||records[0].oldValue!=='R\ud800Z'||records[0].oldValue.charCodeAt(1)!==55296||records[1].oldValue!==''||records[0].target!==x||records[1].target!==x||wrong.takeRecords().length||attr.ownerElement!==null||attr.value!==''||x.noShade!==false)throw 'filtered lowercase boolean observation';}"#);}
